"""Compare the configurations that own the LLVM runtime objects on native Linux."""
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess

tmp = Path(os.environ["RUNNER_TEMP"])
report = {}
targets = [
    "//runsc/boot/filter:filter_precompiled",
    "//runsc/gofer/net/filter:filter_precompiled",
    "//runsc:version_test",
    "//runsc/gofer/net:netgofer_test",
    "//test/syscalls:uname_test_native",
]
platform = "//test/rbe:linux_amd64"
extra = "--extra_execution_platforms=" + platform
host = "--host_platform=" + platform
target = "--platforms=//tools/bazeldefs:linux_amd64"
objects = {
    "external/llvm+/runtimes/glibc/_objs/libm/m.pic.o": ("b4fb763b2", "1de1a9129"),
    "external/llvm+/runtimes/_objs/empty/empty.pic.o": ("92a674c3c", "53865be7f"),
}
# Only release build-option values. Other differences retain their names and
# value hashes so a missing allowlist entry is visible in the result.
safe_options = {
    "cpu", "host_cpu", "compiler", "platforms", "host_platform",
    "extra_execution_platforms", "platform_suffix", "is_exec_configuration",
    "compilation_mode", "affected_by_starlark_transition", "features",
    "host_features", "platform_mappings", "crosstool_top", "force_pic",
    "experimental_platform_in_output_dir", "action_env", "host_action_env",
}

def project(option, value):
    if value is None:
        return None
    value = str(value)
    if option in safe_options - {"action_env", "host_action_env"} and re.fullmatch(r"[A-Za-z0-9@/:+_.,= \[\]-]{0,320}", value):
        return value
    return {"sha256": hashlib.sha256(value.encode()).hexdigest()}

def compare(left, right):
    proc = subprocess.run(["bazelisk", "config", "--output=json", left, right],
                          capture_output=True, text=True)
    if proc.returncode:
        return {"exit": proc.returncode}
    parsed = json.loads(proc.stdout)
    differences = {}
    for fragment in parsed.get("fragmentsDiff", []):
        for option, values in fragment.get("optionsDiff", {}).items():
            values = values if isinstance(values, dict) else {"values": values}
            differences[option] = {k: project(option, v) for k, v in values.items()}
    return {"left": left, "right": right, "differences": differences}

def phase(name, options):
    args = ["bazelisk", "test", "--nobuild", "--keep_going", "--jobs=64",
            "--define=source_presubmit=true", "--strip=never", "--test_env=CGROUPV2=true",
            *options, *targets]
    log = tmp / (name + ".log")
    with log.open("wb") as output:
        proc = subprocess.run(args, stdout=output, stderr=subprocess.STDOUT, timeout=1200)
    raw = log.read_text(errors="replace")
    item = report[name] = {
        "analysis_exit": proc.returncode,
        "collision_count": raw.count("is generated by these conflicting actions"),
        "configurations": {},
        "known_diagnostics": [s for s in ("not all targets were analyzed", "No test targets were found",
            "no matching execution platform", "fetch of repository", "OutOfMemoryError",
            "No space left on device", "Build did NOT complete successfully") if s in raw],
    }
    for path, historical in objects.items():
        marker = "file '" + path + "' is generated by these conflicting actions:"
        block = raw.partition(marker)[2].partition("\nERROR:")[0]
        ids = re.search(r"(?m)^\s*Configuration: ([0-9a-f]{64}), ([0-9a-f]{64})\s*$", block)
        if ids or name == "original":
            item["configurations"][path] = compare(*(ids.groups() if ids else historical))
    if name == "original" and not any(
            record.get("differences") for record in item["configurations"].values()):
        # The full configuration hashes may vary with runner startup options.
        # Ask the same Bazel server for the configured instances in this graph.
        query = 'filter("runtimes(/glibc)?:(empty|libm)$", deps(set(' + " ".join(targets) + ')))'
        result = subprocess.run(["bazelisk", "cquery", "--define=source_presubmit=true",
                                 "--strip=never", "--test_env=CGROUPV2=true", *options, query],
                                capture_output=True, text=True, timeout=900)
        item["query_exit"] = result.returncode
        instances = {}
        for label, config in re.findall(r"(?m)^([^ ]+/runtimes(?:/glibc)?:(?:empty|libm)) \(([0-9a-f]{7,64})\)$", result.stdout):
            instances.setdefault(label, []).append(config)
        item["additional_configuration_pairs"] = [
            compare(configs[i], configs[j]) for configs in instances.values()
            for i in range(min(6, len(configs))) for j in range(i + 1, min(6, len(configs)))
        ]
    (tmp / "llvm-config-comparison.json").write_text(json.dumps(report, indent=2))
    log.unlink()

phase("original", [extra])
phase("one_execution_platform", [host])
phase("one_execution_platform_with_explicit_target", [host, target])
phase("default_execution_platform", [])
